import { allowedDeps, type Manifest, type ManifestNode } from './manifest.ts'
import { escapeRegex } from './workspace.ts'

/** Repo-relative paths of the files the generator owns. */
export const DEPCRUISE_CONFIG: string = '.dependency-cruiser.json'
export const GENERATED_DIR: string = 'tooling/boundaries/generated'
export const BIOME_PLUGINS: string = `${GENERATED_DIR}/biome-plugins.json`
export const NEUTRAL_PLUGIN: string = 'tooling/boundaries/grit/neutral-no-dialect-compare.grit'

const HEADER =
  'Generated by tooling/boundaries from packages.json. Do not edit: run `pnpm boundaries:write`.'

/** Any import that lands in the workspace: a package file, or a workspace name that didn't resolve. */
const WORKSPACE_TARGET = '^(?:packages|tooling)/|^@provino/|^provino(?:-|/|$)'
const DIALECT_TARGET = '^packages/dialect-[^/]+/|^@provino/dialect-'

/**
 * Every generated file, by repo-relative path, as it should be on disk.
 * @public
 */
export function generate(manifest: Manifest): ReadonlyMap<string, string> {
  const files = new Map<string, string>()
  files.set(DEPCRUISE_CONFIG, json(depcruiseConfig(manifest)))
  const groups = sliceGroups(manifest)
  for (const group of groups)
    files.set(`${GENERATED_DIR}/${group.file}`, sliceGrit(manifest, group))
  files.set(BIOME_PLUGINS, json(biomePlugins(manifest, groups)))
  return files
}

interface SliceGroup {
  readonly key: string
  readonly file: string
  readonly allowed: readonly string[]
  readonly dirs: readonly string[]
}

/** Packages that may import the same slices share one plugin file. */
function sliceGroups(manifest: Manifest): readonly SliceGroup[] {
  const groups = new Map<string, { allowed: readonly string[]; dirs: string[] }>()
  for (const node of manifest.nodes) {
    if (node.parent !== undefined || node.dir === null || node.slices === 'all') continue
    const allowed = [...node.slices].sort()
    const key = allowed.length === 0 ? 'none' : allowed.join('+')
    const group = groups.get(key) ?? { allowed, dirs: [] }
    group.dirs.push(`${node.dir}/**`)
    groups.set(key, group)
  }
  return [...groups.entries()]
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([key, group]) => ({
      key,
      file: `slice-discipline.${key}.grit`,
      allowed: group.allowed,
      dirs: group.dirs.sort(),
    }))
}

function sliceGrit(manifest: Manifest, group: SliceGroup): string {
  const allowedTypes = group.allowed.map((slice) => manifest.slices[slice] ?? slice)
  const forbidden = [
    ...manifest.wholePolicyTypes,
    ...Object.entries(manifest.slices)
      .filter(([slice]) => !group.allowed.includes(slice))
      .map(([, type]) => type),
  ]
  const may =
    allowedTypes.length === 0
      ? 'may import no policy slice type'
      : `may import only its own policy slice type (${allowedTypes.join(', ')})`
  const message = `slice-discipline: this package ${may}; other slices and the whole Policy belong to other packages. See monorepo-architecture.md, rule 3.`
  return [
    `// ${HEADER}`,
    `// Packages: ${group.dirs.join(', ')}`,
    'language js',
    '',
    'or {',
    ...forbidden.map((type) => `  \`${type}\`,`),
    '  JsNamedImportSpecifier(name = $name),',
    '  JsExportNamedFromSpecifier(source_name = $name)',
    '} as $hit where {',
    `  or { $name <: undefined, $name <: r"(?:${forbidden.join('|')})" },`,
    `  register_diagnostic(span = $hit, message = "${message}")`,
    '}',
    '',
  ].join('\n')
}

function biomePlugins(manifest: Manifest, groups: readonly SliceGroup[]): unknown {
  const neutralDirs = manifest.nodes
    .filter((node) => node.parent === undefined && node.neutral && node.dir !== null)
    .map((node) => `${node.dir}/**`)
    .sort()
  return {
    plugins: [
      {
        path: '../grit/neutral-no-dialect-compare.grit',
        resolutionKind: 'config',
        includes: neutralDirs,
      },
      ...groups.map((group) => ({
        path: `./${group.file}`,
        resolutionKind: 'config',
        includes: group.dirs,
      })),
    ],
  }
}

function depcruiseConfig(manifest: Manifest): unknown {
  const placed = manifest.nodes.filter((node) => node.dir !== null)
  const neutral = placed.filter((node) => node.neutral).map((node) => owned(manifest, node))
  return {
    $schema:
      'https://raw.githubusercontent.com/sverweij/dependency-cruiser/main/src/schema/configuration.schema.json',
    forbidden: [
      {
        name: 'neutral-no-dialect',
        comment: 'Neutral packages never import a dialect (CLAUDE.md non-negotiable 1).',
        severity: 'error',
        from: { path: neutral },
        to: { path: DIALECT_TARGET },
      },
      ...placed.map((node) => boundaryRule(manifest, node)),
      {
        name: 'public-entry-only',
        comment:
          'Cross-package imports use the package name and its exports, never a relative path.',
        severity: 'error',
        from: { path: '^(packages|tooling)/([^/]+)/' },
        to: { dependencyTypes: ['local'], path: '^(?:packages|tooling)/', pathNot: '^$1/$2/' },
      },
      {
        name: 'not-to-unresolvable',
        comment: "Every import resolves. A deep import past a package's exports fails here.",
        severity: 'error',
        from: {},
        to: { couldNotResolve: true },
      },
      {
        name: 'no-circular',
        comment:
          'No dependency cycles (monorepo-architecture.md, rule 7). A cycle made only of type-only imports erases at compile time, so it is allowed: contract types refer to each other.',
        severity: 'error',
        from: {},
        to: { circular: true, viaOnly: { dependencyTypesNot: ['type-only'] } },
      },
    ],
    options: {
      doNotFollow: { path: 'node_modules' },
      exclude: { path: '(^|/)(?:node_modules|dist|\\.tsc|\\.turbo)/' },
      tsPreCompilationDeps: true,
      combinedDependencies: false,
      enhancedResolveOptions: {
        exportsFields: ['exports'],
        conditionNames: ['provino-source', 'types', 'import', 'node', 'default'],
        extensions: ['.ts', '.js', '.json'],
        mainFields: ['types', 'module', 'main'],
      },
    },
  }
}

function boundaryRule(manifest: Manifest, node: ManifestNode): unknown {
  const deps = allowedDeps(manifest, node)
  const allowedNames = deps.map((dep) => dep.name).sort()
  const layer = typeof node.layer === 'number' ? `layer ${node.layer}` : node.layer
  return {
    name: `boundary-${node.name
      .replace(/^@provino\//, '')
      .replaceAll('/', '-')
      .replaceAll('*', 'x')}`,
    comment: `${node.name} (${layer}, runs in ${node.runsIn}) may import only: ${
      allowedNames.length === 0 ? 'no workspace package' : allowedNames.join(', ')
    }.`,
    severity: 'error',
    from: { path: owned(manifest, node) },
    to: {
      path: WORKSPACE_TARGET,
      pathNot: [
        owned(manifest, node),
        ...deps.flatMap((dep) => (dep.dir === null ? [] : [owned(manifest, dep)])),
        ...deps.map((dep) => `^${pattern(dep.name)}$`),
      ],
    },
  }
}

/** The files a node owns: its dir, minus the dirs of its subpath entries. */
function owned(manifest: Manifest, node: ManifestNode): string {
  if (node.dir === null) throw new Error(`${node.name} has no dir`)
  const dir = node.dir
  const children = manifest.nodes
    .filter((child) => child.parent === node.name && child.dir !== null)
    .map((child) => escapeRegex(String(child.dir).slice(dir.length + 1)))
  const except = children.length === 0 ? '' : `(?!(?:${children.join('|')})/)`
  return `^${pattern(dir)}/${except}`
}

/** A manifest name or dir as a RegExp source; `*` matches one path segment. */
function pattern(text: string): string {
  return text.split('*').map(escapeRegex).join('[^/]+')
}

function json(value: unknown): string {
  return `${JSON.stringify(value, null, 2)}\n`
}
